-- Unterweisungen in kurze Abschnitte mit Bild aufteilen: nach Abschnitt n kommt Frage n.
-- Die Fragen bleiben unverändert (gleiche IDs), nur der Lesetext wird ersetzt.
-- „punkte“ ist immer gesetzt (auch leer), damit ältere App-Versionen nicht abstürzen.

update public.unterweisungen set inhalt = '[{"titel":"Gefahr erkannt?","text":"Du achtest auf dich und deine Kollegen. Kannst du eine Gefahr nicht selbst sicher beseitigen, sicherst du die Stelle ab und meldest sie sofort.","bild":"melden","punkte":[]},{"titel":"Notruf 112","text":"Unter 112 erreichst du in ganz Europa Rettungsdienst und Feuerwehr. Die Polizei hat in Deutschland die 110.","bild":"notruf","punkte":[]},{"titel":"Was sage ich am Telefon?","text":"Beim Notruf beantwortest du diese Fragen:","punkte":["Wo ist es passiert?","Was ist passiert?","Wie viele Verletzte?","Welche Verletzungen?","Warten, ob die Leitstelle noch Fragen hat. Nicht selbst auflegen."],"bild":"w_fragen"},{"titel":"Erst Eigenschutz","text":"An einer Unfallstelle schützt du zuerst dich: Warnweste an, Stelle absichern. Erst dann hilfst du den Verletzten.","bild":"eigenschutz","punkte":[]},{"titel":"Auch kleine Verletzungen melden","text":"Jede Verletzung wird versorgt, gemeldet und ins Verbandbuch eingetragen. Nur so bist du später abgesichert, falls doch Folgen auftreten.","bild":"verbandbuch","punkte":[]},{"titel":"Alkohol baut sich langsam ab","text":"Der Körper baut nur etwa 0,1 Promille pro Stunde ab. Wer abends viel trinkt, hat morgens oft noch Restalkohol.","bild":"promille","punkte":[]},{"titel":"Kein Trick hilft","text":"Kaffee, kalte Dusche oder Schlaf machen nicht nüchtern. Nur die Zeit hilft. Unter Alkohol, Drogen oder starken Medikamenten fährst du nicht und bedienst keine Geräte.","bild":"kaffee","punkte":[]},{"titel":"Richtig heben","text":"Lasten hebst du aus den Knien, mit geradem Rücken und nah am Körper. Unter Last nicht verdrehen. Schweres mit Hubwagen oder zu zweit.","bild":"heben","punkte":[]},{"titel":"Sicher aussteigen","text":"Rückwärts aussteigen, Haltegriffe und Trittstufen nutzen: immer drei Punkte Kontakt. Nicht aus dem Fahrerhaus springen.","bild":"aussteigen","punkte":[]},{"titel":"Feuerlöscher","text":"Feuerlöscher müssen frei erreichbar und geprüft sein. Ist die Prüfplakette abgelaufen, meldest du das, damit er geprüft oder ersetzt wird.","bild":"feuerloescher","punkte":[]}]'::jsonb, version = 2
 where schluessel = 'arbeitsschutz';

update public.unterweisungen set inhalt = '[{"titel":"Jeden Tag vor der Abfahrt","text":"Die Abfahrtskontrolle machst du täglich vor Fahrtantritt und bei jedem Fahrzeugwechsel neu. Einmal rund ums Fahrzeug: Reifen, Licht, Bremsen, Ladung, Papiere.","bild":"rundgang","punkte":[]},{"titel":"Das ist Arbeitszeit","text":"Die Zeit für die Kontrolle trägst du im Tachographen als Arbeit ein (Hammer-Symbol), nicht als Pause.","bild":"tacho_hammer","punkte":[]},{"titel":"Du bist verantwortlich","text":"Nach § 23 StVO ist der Fahrer verantwortlich, dass Fahrzeug und Ladung vorschriftsmäßig und verkehrssicher sind.","bild":"verantwortung","punkte":[]},{"titel":"Schwerer Mangel: nicht losfahren","text":"Ist die Verkehrssicherheit beeinträchtigt, z. B. Bremse, Lenkung, Reifen oder Licht, fährst du nicht los. Mangel in der App eintragen und sofort Disposition oder Verkehrsleiter anrufen.","bild":"stopp","punkte":[]},{"titel":"In der App dokumentieren","text":"Die Kontrolle machst du vollständig in dieser App: Fahrzeug wählen, alle Punkte abarbeiten, unterschreiben, abschicken.","bild":"app","punkte":[]},{"titel":"Mangel mit Foto","text":"Zu jedem Mangel schreibst du kurz, was defekt ist, und machst ein Foto. Der Verkehrsleiter wird sofort benachrichtigt.","bild":"foto","punkte":[]},{"titel":"Werte aus der Betriebsanleitung","text":"Reifendruck, Füllstände und Betriebsstoffe richten sich nach der Betriebsanleitung des Herstellers. Nicht schätzen.","bild":"anleitung","punkte":[]},{"titel":"Warnmeldung im Display","text":"Leuchtet eine rote Warnung, hältst du an, sobald es sicher geht, schaust in die Anleitung und meldest es sofort.","bild":"warnleuchte","punkte":[]},{"titel":"Assistenzsysteme","text":"ABS, ESP, Abstandsregler und Notbremsassistent helfen dir. Abschalten oder manipulieren ist verboten.","bild":"assistenz","punkte":[]},{"titel":"Anleitung an Bord","text":"Die Betriebsanleitung des Herstellers muss immer im Fahrzeug sein. Bei neuen Fahrzeugen machst du dich vor der ersten Fahrt mit allen Bedienelementen vertraut.","bild":"anleitung","punkte":[]}]'::jsonb, version = 2
 where schluessel = 'abfahrtskontrolle';

update public.unterweisungen set inhalt = '[{"titel":"Kräfte beim Bremsen","text":"Bei einer Vollbremsung drückt die Ladung mit bis zu 80 % ihres Gewichts nach vorn. Eine Palette mit 1.000 kg drückt also mit etwa 800 kg gegen die Stirnwand.","bild":"kraefte_vorn","punkte":[]},{"titel":"Kräfte zur Seite und nach hinten","text":"In Kurven und beim Ausweichen wirken bis zu 50 % des Gewichts zur Seite. Beim Anfahren sind es bis zu 50 % nach hinten.","bild":"kraefte_seite","punkte":[]},{"titel":"Antirutschmatten","text":"Reibung allein hält die Ladung nicht. Antirutschmatten erhöhen die Reibung stark, so brauchst du weniger Zurrgurte.","bild":"antirutsch","punkte":[]},{"titel":"Formschluss ist am besten","text":"Ladung lückenlos an die Stirnwand und aneinander stellen. Lücken schließt du mit Klemmstangen, Zwischenwandverschluss oder Polstern.","bild":"formschluss","punkte":[]},{"titel":"Kaputte Gurte aussortieren","text":"Gurte mit Schnitten, Rissen, kaputten Nähten, verbogener Ratsche oder ohne lesbares Etikett werden nicht mehr benutzt. Gurte nie knoten.","bild":"gurt_defekt","punkte":[]},{"titel":"Das Etikett am Gurt","text":"LC ist die Zurrkraft im geraden Zug. STF ist die Vorspannkraft beim Niederzurren, also wie stark der Gurt die Ladung auf den Boden drückt.","bild":"etikett","punkte":[]},{"titel":"Kantenschutz","text":"An scharfen Kanten schützt der Kantenschutz den Gurt vor dem Durchscheuern und die Ladung vor Schäden.","bild":"kantenschutz","punkte":[]},{"titel":"Wer ist verantwortlich?","text":"Der Verlader sorgt für die beförderungssichere Verladung. Du als Fahrer bist für die verkehrssichere Ladung während der Fahrt verantwortlich. Ist sie nicht sicher, fährst du nicht los.","bild":"verlader_fahrer","punkte":[]},{"titel":"Material an Bord","text":"Vor der Abfahrt prüfst du das Sicherungsmaterial. Fehlt etwas oder ist es kaputt: melden und in der Abfahrtskontrolle eintragen.","punkte":["8 Zurrgurte","3 Klemmstangen","Antirutschmatten","10 Kantenschützer","1 Zwischenwandverschluss","1 Bordwandhalter mit Ratsche"],"bild":"material"},{"titel":"Unterwegs nachprüfen","text":"Nach den ersten Kilometern, nach Zwischenstopps und nach Teilentladungen prüfst du die Sicherung erneut und spannst die Gurte nach.","bild":"nachpruefen","punkte":[]}]'::jsonb, version = 2
 where schluessel = 'ladungssicherung';

update public.unterweisungen set inhalt = '[{"titel":"Tägliche Lenkzeit","text":"Du darfst am Tag höchstens 9 Stunden lenken.","bild":"lenkzeit_tag","punkte":[]},{"titel":"Zweimal 10 Stunden","text":"Zweimal pro Woche darfst du die tägliche Lenkzeit auf 10 Stunden verlängern.","bild":"woche_10h","punkte":[]},{"titel":"Woche und Doppelwoche","text":"In einer Woche höchstens 56 Stunden lenken. In zwei Wochen zusammen höchstens 90 Stunden.","bild":"doppelwoche","punkte":[]},{"titel":"Pause nach 4,5 Stunden","text":"Nach spätestens 4,5 Stunden Lenkzeit machst du mindestens 45 Minuten Pause.","bild":"pause","punkte":[]},{"titel":"Pause aufteilen","text":"Die Pause darfst du teilen: erst mindestens 15 Minuten, dann mindestens 30 Minuten. Andersherum zählt es nicht.","bild":"pause_teilen","punkte":[]},{"titel":"Tägliche Ruhezeit","text":"Die tägliche Ruhezeit beträgt mindestens 11 Stunden. Dreimal zwischen zwei Wochenruhezeiten darf sie auf 9 Stunden verkürzt werden. Die Wochenruhezeit beträgt mindestens 45 Stunden.","bild":"ruhezeit","punkte":[]},{"titel":"Auslesen","text":"Die Fahrerkarte wird spätestens alle 28 Tage ausgelesen, der Massenspeicher im Fahrzeug spätestens alle 90 Tage.","bild":"auslesen","punkte":[]},{"titel":"Nachträge","text":"Fahrerkarte vor Fahrtbeginn stecken. Tätigkeiten ohne gesteckte Karte, z. B. Werkstatt, Büro oder Urlaub, trägst du als manuellen Nachtrag mit der richtigen Tätigkeit ein.","bild":"nachtrag","punkte":[]},{"titel":"Karte defekt oder verloren","text":"Sofort melden. Bis zur Ersatzkarte machst du zu Beginn und Ende jeder Fahrt einen Ausdruck, schreibst Name und Kartennummer drauf und unterschreibst. Manipulation ist eine Straftat.","bild":"karte_defekt","punkte":[]},{"titel":"Tacho und Arbeitszeit gleich","text":"Deine erfassten Arbeitszeiten müssen mit dem Tachographen übereinstimmen. Abweichungen meldest du sofort dem Büro.","bild":"abgleich","punkte":[]}]'::jsonb, version = 2
 where schluessel = 'tacho';

update public.unterweisungen set inhalt = '[{"titel":"Ohne ADR-Schein","text":"Ohne ADR-Bescheinigung darfst du Gefahrgut nur nach der 1000-Punkte-Regel oder als begrenzte Menge (LQ) fahren.","bild":"adr_ohne","punkte":[]},{"titel":"Grenze 1000 Punkte","text":"Über 1000 Punkte ist ohne gültigen ADR-Schein verboten. Ist es mehr, lädst du nicht und klärst es mit Disposition oder Verkehrsleiter.","bild":"punkte_grenze","punkte":[]},{"titel":"So wird gerechnet","text":"Jeder Stoff hat eine Beförderungskategorie. Die Menge wird mit dem Faktor malgenommen, alles zusammen darf 1000 nicht übersteigen.","punkte":["Kategorie 1: Menge × 50","Kategorie 2: Menge × 3","Kategorie 3: Menge × 1"],"bild":"punkte_rechnung"},{"titel":"Nur dichte Versandstücke","text":"Beschädigte oder undichte Versandstücke nimmst du nicht an und meldest sie.","bild":"undicht","punkte":[]},{"titel":"Beförderungspapier","text":"Bei der 1000-Punkte-Regel muss das Beförderungspapier mitfahren. Bei uns liegen zusätzlich die schriftlichen Weisungen im Fahrzeug.","bild":"papier","punkte":[]},{"titel":"Feuerlöscher 2 kg","text":"Mindestens ein 2-kg-Feuerlöscher für die Brandklassen A, B und C muss an Bord sein. Die Gefahrgutausrüstung prüfst du vor jedem Transport.","bild":"feuerloescher_2kg","punkte":[]},{"titel":"Das LQ-Zeichen","text":"Begrenzte Mengen erkennst du an der Raute auf der Spitze: oben und unten schwarz, in der Mitte weiß, mindestens 100 × 100 mm.","bild":"lq_raute","punkte":[]},{"titel":"LQ höchstens 30 kg","text":"Ein LQ-Versandstück wiegt höchstens 30 kg brutto. Ein Beförderungspapier brauchst du dafür nicht, die Gesamtmenge muss aber bekannt sein.","bild":"lq_30kg","punkte":[]},{"titel":"Rauchverbot","text":"Beim Be- und Entladen und in der Nähe der Ladung gilt Rauch- und Feuerverbot, auch für E-Zigaretten.","bild":"rauchverbot","punkte":[]},{"titel":"Wenn etwas passiert","text":"Bei Unfall, Leck oder Brand: eigene Sicherheit zuerst, Motor aus, Unfallstelle sichern, 112 rufen. Keine riskanten Eigenmaßnahmen, wenn möglich nach den schriftlichen Weisungen handeln.","bild":"gefahrgut_unfall","punkte":[]}]'::jsonb, version = 2
 where schluessel = 'gefahrgut';

update public.unterweisungen set inhalt = '[{"titel":"Wer darf die Ladebordwand bedienen?","text":"Nur unterwiesene und beauftragte Personen. Kunden oder Fremde bedienen sie nicht.","bild":"lbw","punkte":[]},{"titel":"Vor jeder Benutzung prüfen","text":"Sicht- und Funktionsprüfung: Hydraulik, Bedienelemente, Prüfplakette noch gültig. Die Traglast wird nie überschritten.","bild":"lbw_pruefen","punkte":[]},{"titel":"Nicht springen","text":"Von der Bühne wird nie gesprungen. Auf- und Absteigen nur kontrolliert über die Absenkfunktion. Abstand zur Kante halten, bei Nässe und Eis besonders vorsichtig.","bild":"lbw_springen","punkte":[]},{"titel":"Gefahrenbereich frei","text":"Während die Bühne fährt, hält sich niemand darunter oder daneben auf. Quetschgefahr!","bild":"lbw_gefahr","punkte":[]},{"titel":"Mangel: Finger weg","text":"Verliert die Ladebordwand Öl oder funktioniert sie nicht richtig, benutzt du sie nicht und meldest es sofort.","bild":"lbw_oel","punkte":[]},{"titel":"Elektro-Ameise: wer darf?","text":"Nur unterwiesene Personen ab 18 Jahren, körperlich und geistig geeignet. Nie unter Alkohol, Drogen oder starken Medikamenten.","bild":"ameise_18","punkte":[]},{"titel":"Tägliche Prüfung der Ameise","text":"Vor Arbeitsbeginn prüfst du:","punkte":["Sichtprüfung auf Schäden","Heben und Senken","Fahrantrieb und Deichsel","Not-Aus","Ladezustand der Batterie"],"bild":"ameise_pruefen"},{"titel":"Höchstens 1200 kg","text":"Unsere Ameise trägt höchstens 1200 kg. Last gleichmäßig aufnehmen, nur auf ebenem, festem Boden, langsam auf Ladefläche und Rampe.","bild":"ameise_1200","punkte":[]},{"titel":"Niemand fährt mit","text":"Mitfahren, Personen heben und ruckartiges Fahren sind verboten. Hände und Füße bleiben aus dem Gefahrenbereich.","bild":"ameise_mitfahren","punkte":[]},{"titel":"Kein Zuggerät","text":"Die Ameise ist kein Zug- oder Abschleppgerät. Mit Mängeln wird sie nicht benutzt.","bild":"ameise_ziehen","punkte":[]}]'::jsonb, version = 2
 where schluessel = 'ladebordwand_ameise';

update public.unterweisungen set inhalt = '[{"titel":"Handy weg","text":"Während der Fahrt nimmst du das Handy nicht in die Hand, auch nicht an der Ampel. Telefonieren nur über die Freisprecheinrichtung, Navi vor der Abfahrt einstellen.","bild":"handy","punkte":[]},{"titel":"Müde? Anhalten!","text":"Gähnen, schwere Augen, Spur halten fällt schwer: sofort an einem sicheren Ort anhalten und Pause machen. Sekundenschlaf kann tödlich sein.","bild":"muedigkeit","punkte":[]},{"titel":"50 Meter Abstand","text":"LKW über 3,5 t halten auf der Autobahn ab 50 km/h mindestens 50 m Abstand. Das ist der Abstand von einem Leitpfosten zum nächsten.","bild":"abstand","punkte":[]},{"titel":"Rechts abbiegen: Schrittgeschwindigkeit","text":"Innerorts biegst du mit einem LKW über 3,5 t nur mit Schrittgeschwindigkeit rechts ab, wenn Radfahrer oder Fußgänger zu erwarten sind.","bild":"abbiegen","punkte":[]},{"titel":"Rettungsgasse","text":"Bei Stau sofort eine Rettungsgasse bilden: zwischen der ganz linken Spur und allen anderen Spuren.","bild":"rettungsgasse","punkte":[]},{"titel":"Toter Winkel","text":"Spiegel richtig einstellen. Der Abbiegeassistent hilft, ersetzt aber nicht deinen Blick. Im Zweifel anhalten und warten.","bild":"toter_winkel","punkte":[]},{"titel":"Warndreieck","text":"Innerorts etwa 50 m, auf der Landstraße etwa 100 m, auf der Autobahn etwa 200 m vor der Unfallstelle aufstellen.","bild":"warndreieck","punkte":[]},{"titel":"Warnweste zuerst","text":"Warnblinker an, Warnweste anziehen, dann erst aussteigen und auf die Fahrbahn gehen. Danach 112 anrufen und Disposition informieren.","bild":"warnweste","punkte":[]},{"titel":"Kein Schuldanerkenntnis","text":"Daten der Beteiligten und Zeugen aufnehmen, Fotos machen. Ein Schuldanerkenntnis unterschreibst du nicht.","bild":"schuld","punkte":[]},{"titel":"Belastende Ereignisse","text":"Ein schwerer Unfall oder eine Bedrohung kann seelisch belasten. Reden hilft: mit dem Vorgesetzten, Kollegen oder Arzt. Die BG Verkehr bietet schnelle psychologische Hilfe.","bild":"reden","punkte":[]}]'::jsonb, version = 2
 where schluessel = 'strassenverkehr';
